const filled = subs.map(s => { const e = Math.min(s.cap, Math.max(0,rem)); rem -= e; return e; });
const reveal = (t * 4) % (Z + 6);
let cfg = "";
for (let i = 0; i < subs.length; i++) {
  if (filled[i] > 0) cfg += subs[i].n + subs[i].l + "^" + filled[i] + " ";
}
H.text("Z = " + Z + "    [" + cfg.trim() + "]", 24, 52, { color: H.colors.sub, size: 13, maxWidth: H.W - 48 });
const x0 = 70, top = 110, rowH = 64, perRow = 4, boxW = 150, boxH = 50;
let count = 0;
for (let i = 0; i < subs.length; i++) {
  const col = i % perRow, row = Math.floor(i / perRow);
  const bx = x0 + col * (boxW + 30);
  const by = top + row * rowH;
  const active = filled[i] > 0;
  H.rect(bx, by, boxW, boxH, { stroke: active ? H.colors.accent : H.colors.grid, width: active ? 2 : 1, radius: 6 });
  H.text(subs[i].n + subs[i].l, bx + 10, by + 30, { color: active ? H.colors.ink : H.colors.sub, size: 16, weight: 700 });
  for (let e = 0; e < subs[i].cap; e++) {
    const ex = bx + 46 + (e % 5) * 18;
    const ey = by + 16 + Math.floor(e / 5) * 20;
    const here = (count + e) < reveal;
    const present = e < filled[i];
    H.circle(ex, ey, 5, { fill: present && here ? H.colors.yellow : H.colors.panel, stroke: H.colors.grid, width: 1 });
  }
  count += filled[i];
}
